/**
 * Project media, generated by scripts/gen-media.mjs into public/media/<slug>/.
 * Every poster is 16:10 at 640 and 1024 wide, in AVIF and WebP.
 *
 * Posters are decorative: the project name sits right beside each one, so the
 * images carry alt="". `preview` is a moving version played on hover only,
 * never preloaded.
 */
export type ProjectMedia = {
  poster: string
  preview?: { src: string; type: 'video/webm' | 'image/webp' }
}

const posterBase = (slug: string) => `/media/${slug}/poster`

export const projectMedia: Record<string, ProjectMedia> = {
  hirelens: {
    poster: posterBase('hirelens'),
    preview: { src: '/media/hirelens/preview.webp', type: 'image/webp' },
  },
  searchscribe: { poster: posterBase('searchscribe') },
  forecastgpt: {
    poster: posterBase('forecastgpt'),
    preview: { src: '/media/forecastgpt/preview.webp', type: 'image/webp' },
  },
  ydirect: {
    poster: posterBase('ydirect'),
    preview: { src: '/media/ydirect/tour.webm', type: 'video/webm' },
  },
}

export const POSTER_WIDTHS = [640, 1024] as const
